ruleToc.chapterName:
$.chaptername##第(\d+|\s\d+\s)章\s*|[第]?[零一二三四五六七八九十百千万两]+章\s*|(?=^)\d+(?=$)
<js>
pointMeassge = java.getString("$.pointMeassge");
java.put("pointmeassge",pointMeassge);
chapterid = java.getString("$.chapterid");
chaptertype = java.getString("$.chaptertype");
islockMessage = java.getString("$.islockMessage") =='[本章节已锁定]'?'[本章节已锁定]':'';
isvip = java.getString("$.isvip") == '0'?'':'💰';
ChapterName = chaptertype=="0"?isvip+'第'+chapterid+'章 '+result+islockMessage:result
</js>

ruleToc.updateTime:
$.chapterintro##(?![A-Za-z0-9]+)\s*(?![A-Za-z0-9]+)
<js>
java.put("chapterintro",result);
chapterintro = result;
chapterdate = java.getString("$.chapterdate");
chaptersize = java.getString("$.chaptersize");
chaptertype = java.getString("$.chaptertype");
ChapterInfo = chaptertype=="0"?chapterdate+'　'+chaptersize+'字'+'　'+chapterintro:""
</js>

ruleSearch.bookList:
.book-list li@js:
result.toArray().map(o =>{
    var detail= String(o.select('.book-name').attr('href')).replace(/^\//, baseUrl.match(/(.+\/\/.+?\/)/)[1]);
    var oText = s=>String(o.select(s).text().trim());
    var J = org.jsoup.Jsoup.parse(java.ajax(detail));
    var jText = s=>String(J.select(s).text().trim());
    return {
        name: oText('.book-name'),
        author: oText('.smaller').replace(/\s*作者：(\S+).+/, '$1'),
        tags: [String(J.select('.book-title .tag').toArray().map(tag =>tag.text()).join(' / '),J.select('.book-info > .row .tag').toArray().map(tag =>String(tag.text())).filter(v =>v.length < 5).slice(0, 2).join(','))].join(','),
        num:jText('.book-info-numbers span:eq(0)').replace(/●|总字数：/g, '')+'字',
        latest: oText('.smaller').replace(/.+\D(\d+-\d+-\d+).+\/\s*(.+)/, '$2（$1）').replace(/[\(（【].*[求更谢乐发推].*[】）\)]/,'').replace(/.*(第[^章]+章)/,'$1'),
        intro: jText('.book-brief').replace(/\s*简介：/, '').replace(/[\s\t]+/g, ''),
        cover: o.select('.cover').attr('data-original'),
        catalogUrl: detail
    }
}).filter(v =>v.name);

