ChapterContent@js:
function p(e) {
    return e.split("").map(function (e) {
        return e.match(/[A-Za-z]/) ? (c = Math.floor(e.charCodeAt(0) / 97), k = (e.toLowerCase().charCodeAt(0) - 83) % 26 || 26, String.fromCharCode(k + (0 == c ? 64 : 96))) : e
    }).join("")
}
java.base64Decode(p(result))

ruleToc.chapterList:
@css:
#allchapter>.title, #allchapter>.details

@js:
list=[]
$=result
for(i in $){
if(String($[i]).match(/class="title/)){
	t=String($[i].text()).replace(new RegExp(book.name,''),'').replace(/（.*|\(.*/g,'');
		list.push({
				text: " 【"+t+" 】 ",
				volume: true
			})
	}
else{
		$[i].select("a").forEach(a=>{
				list.push({
						text: a.text(),
						href: a.attr("href")
					})
			})
	}
}
